// 1. Validar status code de creación exitosa (201)
pm.test("Status code es 201 Created", function () {
    pm.response.to.have.status(201);
});

// 2. Validar que la respuesta contenga los campos esperados
pm.test("Validar contrato y datos recibidos", function () {
    const res = pm.response.json();

    pm.expect(res).to.have.property("id");
    pm.expect(res.name).to.eql("Jose Gomez");
    pm.expect(res.job).to.eql("QA Automation Engineer");

    // Guardar el ID de forma dinámica en el entorno para peticiones posteriores
    pm.environment.set("userId", res.id);
});
